function set_up(container) {
            var prev = container.find('.pagination .prev');
            var next = container.find('.pagination .next');

            var prev_url = null, next_url = null;

            if (prev.length)
                prev_url = prev.attr('href');
            if (next.length)
                next_url = next.attr('href');

            function ajax(url, handler) {
                if (url[0] != '/' || url[1] == '/')
                    url = (''+location).replace( /[#\?].*/, '') + url;

                if (url.indexOf('&xhr') < 0 && url.indexOf('?xhr') < 0)
                    if (url.indexOf('?') < 0)
                        url += '?xhr';
                    else
                        url += '&xhr';

                $.ajax({
                        type: 'GET',
                        url: url,
                        datatype: "html",
                        cache: true,
                        success: handler,
                        error: function(xhr, ajaxOptions, thrownError) {
                            handler($('<div/>').append(
                                    $('<strong>').append(''+xhr.status + ' ' + thrownError)).html());
                        }
                });
            }

            function showLoader() {
                var loader = $('.paginate-loading').eq(0);

                for (var i in containers)
                {
                    var height = containers[i].height();
                    if (height < 50) height = 50;
                    containers[i].css('height', height + 'px');

                    containers[i].empty();
                    containers[i].append(loader.html());
                }
            }

            function replacePage(url, receivedHtml) {
				if (setHash)
					location.hash = 'page:' + url;


                for (var i in containers) {
                    containers[i].empty();
                    containers[i].css('height', '');

                    receivedHtml = $.trim(receivedHtml);
                    $(receivedHtml).find('.paginate-container').eq(i).each(function() {
                        containers[i].append($(this).html());
                        set_up(containers[i]);
                    });
                }

                $(document).trigger('paginatorPageReplaced', [ containers ]);

                if (location.hash.substr(1).indexOf('#') > 0) {
                    var hash = (''+location.hash).replace( /.*#/, '');
                    scroll(hash);
                }
                else {
                    var paginatorTop = container.offset().top;

                    if (paginatorTop < $(window).scrollTop() || paginatorTop > $(window).scrollTop() + $(window).height()) {
                        $('html,body').animate({scrollTop: paginatorTop}, 350);
                    }
                }
            }

            if (processHash && location.hash.match( /^#page/)) {
                var url = location.hash.replace( /^#page:/, '');
                container.empty();
                ajax(url, function(html) { replacePage(url,html); });
            }
            processHash = false;

            var previousPageHtml = null;
            var nextPageHtml = null;
            var clickedPrevious = false;
            var clickedNext = false;

            var preload = $('.pagination_preload').size() > 0;

            if (preload) {
				if (prev_url)
                    ajax(prev_url, function(html) {
                        previousPageHtml = html;
                        if (clickedPrevious) replacePage(prev_url, html);
                    });
                if (next_url)
                    ajax(next_url, function(html) {
                        nextPageHtml = html;
                        if (clickedNext) replacePage(next_url, html);
                    });

                prev.click(function() {
                    showLoader();
                    if (previousPageHtml)
                        replacePage(prev_url, previousPageHtml);
                    else
                        clickedPrevious = true;
                    return false;
                });

                next.click(function() {
                    showLoader();
                    if (nextPageHtml)
                        replacePage(next_url, nextPageHtml);
                    else
                        clickedNext = true;
                    return false;
                });
            }

            container.find('.pagination a, .pagination-helper a, a.pagination-helper').each(function() {

                $(this).click(function (){
                	var url = $(this).attr('href');
                    showLoader();

                    if (url[0] == '#') {
                        var hash = url.replace( /#/, '');
                        scroll(hash);
                    }
                    else
                        ajax(url, function(html) {
							replacePage(url, html);
                        });
                    return false;
                });
            });

            container.find('form.pagination-form').each(function() {
                var form = $(this);
                if (form.attr('method') == 'get' && form.attr('action').match(/.*?/)) {
                    form.submit(function() {
                        var url = form.attr('action') + form.serialize();

                        ajax(url, function(html) {
                            replacePage(url, html);
                        });
                        return false;
                    });
                }
            });
        }

function listTagsHelper(tags, options) {
  if (!options && (!tags || !Object.prototype.hasOwnProperty.call(tags, 'length'))) {
    options = tags;
    tags = this.site.tags;
  }

  if (!tags || !tags.length) return '';
  options = options || {};

  const { style = 'list', transform, separator = ', ', suffix = '' } = options;
  const showCount = Object.prototype.hasOwnProperty.call(options, 'show_count') ? options.show_count : true;
  const classStyle = typeof style === 'string' ? `-${style}` : '';
  let className, ulClass, liClass, aClass, labelClass, countClass, labelSpan;
  if (typeof options.class !== 'undefined') {
    if (typeof options.class === 'string') {
      className = options.class;
    } else {
      className = 'tag';
    }

    ulClass = options.class.ul || `${className}${classStyle}`;
    liClass = options.class.li || `${className}${classStyle}-item`;
    aClass = options.class.a || `${className}${classStyle}-link`;
    labelClass = options.class.label || `${className}${classStyle}-label`;
    countClass = options.class.count || `${className}${classStyle}-count`;

    labelSpan = Object.prototype.hasOwnProperty.call(options.class, 'label');
  } else {
    className = 'tag';
    ulClass = `${className}${classStyle}`;
    liClass = `${className}${classStyle}-item`;
    aClass = `${className}${classStyle}-link`;
    labelClass = `${className}${classStyle}-label`;
    countClass = `${className}${classStyle}-count`;

    labelSpan = false;
  }
  const orderby = options.orderby || 'name';
  const order = options.order || 1;
  let result = '';

  tags = tags.sort(orderby, order);

  tags = tags.filter(tag => tag.length);

  if (options.amount) tags = tags.limit(options.amount);

  if (style === 'list') {
    result += `<ul class="${ulClass}" itemprop="keywords">`;

    tags.forEach(tag => {
      result += `<li class="${liClass}">`;

      result += `<a class="${aClass}" href="${url_for.call(this, tag.path)}${suffix}" rel="tag">`;
      result += transform ? transform(tag.name) : escapeHTML(tag.name);
      result += '</a>';

      if (showCount) {
        result += `<span class="${countClass}">${tag.length}</span>`;
      }

      result += '</li>';
    });

    result += '</ul>';
  } else {
    tags.forEach((tag, i) => {
      if (i) result += separator;

      result += `<a class="${aClass}" href="${url_for.call(this, tag.path)}${suffix}" rel="tag">`;
      if (labelSpan) {
        result += `<span class="${labelClass}">${transform ? transform(tag.name) : tag.name}</span>`;
      } else {
        result += transform ? transform(tag.name) : tag.name;
      }

      if (showCount) {
        result += `<span class="${countClass}">${tag.length}</span>`;
      }

      result += '</a>';
    });
  }

  return result;
}

