function fastifySwagger (fastify, opts, done) {
  let staticCSP = false
  if (opts.staticCSP === true) {
    const csp = fastify.swaggerCSP
    staticCSP = `default-src 'self'; base-uri 'self'; font-src 'self' https: data:; frame-ancestors 'self'; img-src 'self' data: validator.swagger.io; object-src 'none'; script-src 'self' ${csp.script.join(' ')}; script-src-attr 'none'; style-src 'self' https: ${csp.style.join(' ')}; upgrade-insecure-requests;`
  }
  if (typeof opts.staticCSP === 'string') {
    staticCSP = opts.staticCSP
  }
  if (typeof opts.staticCSP === 'object' && opts.staticCSP !== null) {
    staticCSP = ''
    Object.keys(opts.staticCSP).forEach(function (key) {
      const value = Array.isArray(opts.staticCSP[key]) ? opts.staticCSP[key].join(' ') : opts.staticCSP[key]
      staticCSP += `${key.toLowerCase()} ${value}; `
    })
  }

  if (typeof staticCSP === 'string' || typeof opts.transformStaticCSP === 'function') {
    fastify.addHook('onSend', function (request, reply, payload, done) {
      if (typeof staticCSP === 'string') {
        reply.header('content-security-policy', staticCSP.trim())
      }
      const header = reply.getHeader('content-security-policy')
      if (header && typeof opts.transformStaticCSP === 'function') {
        reply.header('content-security-policy', opts.transformStaticCSP(header))
      }
      done()
    })
  }

  const hooks = Object.create(null)
  if (opts.hooks) {
    const additionalHooks = [
      'onRequest',
      'preHandler'
    ]
    for (const hook of additionalHooks) {
      hooks[hook] = opts.hooks[hook]
    }
  }

  fastify.route({
    url: '/',
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: (req, reply) => {
      reply.redirect(getRedirectPathForTheRootRoute(req.raw.url))
    }
  })

  if (opts.theme) {
    const themePrefix = `${staticPrefix}/theme`
    if (opts.theme.css) {
      for (const cssFile of opts.theme.css) {
        fastify.route({
          url: `${themePrefix}/${cssFile.filename}`,
          method: 'GET',
          schema: { hide: true },
          ...hooks,
          handler: (req, reply) => {
            reply
              .header('content-type', 'text/css; charset=UTF-8')
              .send(cssFile.content)
          }
        })
      }
    }

    if (opts.theme.js) {
      for (const jsFile of opts.theme.js) {
        fastify.route({
          url: `${themePrefix}/${jsFile.filename}`,
          method: 'GET',
          schema: { hide: true },
          ...hooks,
          handler: (req, reply) => {
            reply
              .header('content-type', 'application/javascript; charset=utf-8')
              .send(jsFile.content)
          }
        })
      }
    }

    if (opts.theme.favicon) {
      for (const favicon of opts.theme.favicon) {
        fastify.route({
          url: `${themePrefix}/${favicon.filename}`,
          method: 'GET',
          schema: { hide: true },
          ...hooks,
          handler: (req, reply) => {
            reply
              .header('content-type', favicon.type)
              .send(favicon.content)
          }
        })
      }
    }
  }

  const indexHtmlContent = indexHtml(opts)

  fastify.route({
    url: `${staticPrefix}/index.html`,
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: (req, reply) => {
      reply
        .header('content-type', 'text/html; charset=utf-8')
        .send(indexHtmlContent)
    }
  })

  const swaggerInitializerContent = swaggerInitializer(opts)

  fastify.route({
    url: `${staticPrefix}/swagger-initializer.js`,
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: (req, reply) => {
      reply
        .header('content-type', 'application/javascript; charset=utf-8')
        .send(swaggerInitializerContent)
    }
  })

  const hasTransformSpecificationFn = typeof opts.transformSpecification === 'function'
  const shouldCloneSwaggerObject = opts.transformSpecificationClone ?? true
  const transformSpecification = opts.transformSpecification
  fastify.route({
    url: '/json',
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: hasTransformSpecificationFn
      ? shouldCloneSwaggerObject
        ? function (req, reply) {
          reply.send(transformSpecification(rfdc(fastify.swagger()), req, reply))
        }
        : function (req, reply) {
          reply.send(transformSpecification(fastify.swagger(), req, reply))
        }
      : function (req, reply) {
        reply.send(fastify.swagger())
      }
  })

  fastify.route({
    url: '/yaml',
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: hasTransformSpecificationFn
      ? shouldCloneSwaggerObject
        ? function (req, reply) {
          reply
            .type('application/x-yaml')
            .send(yaml.stringify(transformSpecification(rfdc(fastify.swagger()), req, reply)))
        }
        : function (req, reply) {
          reply
            .type('application/x-yaml')
            .send(yaml.stringify(transformSpecification(fastify.swagger(), req, reply)))
        }
      : function (req, reply) {
        reply
          .type('application/x-yaml')
          .send(fastify.swagger({ yaml: true }))
      }
  })

  fastify.register(fastifyStatic, {
    root: opts.baseDir || path.join(__dirname, '..', 'static'),
    prefix: staticPrefix,
    decorateReply: false
  })

  if (opts.baseDir) {
    fastify.register(fastifyStatic, {
      root: opts.baseDir,
      serve: false
    })

    fastify.route({
      url: '/*',
      method: 'GET',
      schema: { hide: true },
      ...hooks,
      handler: function (req, reply) {
        const file = req.params['*']
        reply.sendFile(file)
      }
    })
  }

  done()
}

function isUrl(string){
  var match = string.match(protocolAndDomainRE);
  if (!match) {
    return false;
  }

  var everythingAfterProtocol = match[1];
  if (!everythingAfterProtocol) {
    return false;
  }

  if (localhostDomainRE.test(everythingAfterProtocol) ||
      nonLocalhostDomainRE.test(everythingAfterProtocol)) {
    return true;
  }

  return false;
}

async function createVerificationObjects(signatureList, literalDataList, keys, date=new Date()) {
  return Promise.all(signatureList.filter(function(signature) {
    return ['text', 'binary'].includes(enums.read(enums.signature, signature.signatureType));
  }).map(async function(signature) {
    return createVerificationObject(signature, literalDataList, keys, date);
  }));
}

function set(target, path, value) {

  let currentTarget = target;

  forEach(path, function(key, idx) {

    if (key === '__proto__') {
      throw new Error('illegal key: __proto__');
    }

    let nextKey = path[idx + 1];
    let nextTarget = currentTarget[key];

    if (isDefined(nextKey) && isNil(nextTarget)) {
      nextTarget = currentTarget[key] = isNaN(+nextKey) ? {} : [];
    }

    if (isUndefined(nextKey)) {
      if (isUndefined(value)) {
        delete currentTarget[key];
      } else {
        currentTarget[key] = value;
      }
    } else {
      currentTarget = nextTarget;
    }
  });

  return target;
}

function getGttsCmdWithArgs(fields) {

	var text = fields.textToSpeech,
		language = fields.language,
		speed = fields.speed,
		speedParam = speed ? ' -s' : '',

		cmd = 'gtts-cli' + ' -l ' + language + speedParam + ' --nocheck \"' + text + '\"' + ' | play -t mp3 -';

	return cmd;
}

function KanbanService(
    $q,
    $window,
    gettextCatalog,
    SharedPropertiesService,
    RestErrorService,
    FilterTrackerReportService
) {
    const headers = {
        "content-type": "application/json",
        "X-Client-UUID": SharedPropertiesService.getUUID(),
    };

    return {
        getArchive,
        getBacklog,
        getItems,
        getArchiveSize,
        getBacklogSize,
        getColumnContentSize,
        collapseColumn,
        expandColumn,
        reorderColumn,
        reorderBacklog,
        reorderArchive,
        expandBacklog,
        collapseBacklog,
        expandArchive,
        collapseArchive,
        moveInBacklog,
        moveInArchive,
        moveInColumn,
        updateKanbanLabel,
        deleteKanban,
        addColumn,
        reorderColumns,
        removeColumn,
        editColumn,
        updateKanbanName,
        removeKanban,
        updateSelectableReports,
    };

    function getAnyColumnItems(url, params) {
        return $q.when(
            get(encodeURI(url), { params }).then((response) => {
                const total = response.headers.get("X-PAGINATION-SIZE");
                return response.json().then((items) => {
                    return { results: augmentItems(items.collection), total };
                });
            })
        );
    }

    function getAnyColumnSize(url, params) {
        return $q.when(
            head(encodeURI(url), { params }).then((response) => {
                return Number.parseInt(response.headers.get("X-PAGINATION-SIZE"), 10);
            })
        );
    }

    function getBacklog(kanban_id, limit, offset) {
        let query_params = { limit, offset };
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnItems(`/api/v1/kanban/${kanban_id}/backlog`, query_params);
    }

    function getArchive(kanban_id, limit, offset) {
        let query_params = { limit, offset };
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnItems(`/api/v1/kanban/${kanban_id}/archive`, query_params);
    }

    function getItems(kanban_id, column_id, limit, offset) {
        let query_params = { column_id, limit, offset };
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnItems(`/api/v1/kanban/${kanban_id}/items`, query_params);
    }

    function getBacklogSize(kanban_id) {
        let query_params = {};
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnSize(`/api/v1/kanban/${kanban_id}/backlog`, query_params);
    }

    function getArchiveSize(kanban_id) {
        let query_params = {};
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnSize(`/api/v1/kanban/${kanban_id}/archive`, query_params);
    }

    function getColumnContentSize(kanban_id, column_id) {
        let query_params = { column_id };
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnSize(`/api/v1/kanban/${kanban_id}/items`, query_params);
    }

    function augmentItems(collection) {
        var is_collapsed = SharedPropertiesService.doesUserPrefersCompactCards();
        collection.forEach(function (item) {
            item.is_collapsed = is_collapsed;
        });

        return collection;
    }

    function reorderAnyColumn(url, dropped_item_id, compared_to) {
        return $q.when(
            patch(encodeURI(url), {
                headers,
                body: JSON.stringify({
                    order: getOrderArgumentsFromComparedTo(dropped_item_id, compared_to),
                }),
            }).catch(catchRestError)
        );
    }

    function reorderColumn(kanban_id, column_id, dropped_item_id, compared_to) {
        return reorderAnyColumn(
            `/api/v1/kanban/${kanban_id}/items?column_id=${column_id}`,
            dropped_item_id,
            compared_to
        );
    }

    function reorderBacklog(kanban_id, dropped_item_id, compared_to) {
        return reorderAnyColumn(
            `/api/v1/kanban/${kanban_id}/backlog`,
            dropped_item_id,
            compared_to
        );
    }

    function reorderArchive(kanban_id, dropped_item_id, compared_to) {
        return reorderAnyColumn(
            `/api/v1/kanban/${kanban_id}/archive`,
            dropped_item_id,
            compared_to
        );
    }

    function moveInAnyColumn(url, dropped_item_id, compared_to, from_column) {
        const patch_arguments = {
            add: {
                ids: [dropped_item_id],
            },
            from_column: from_column,
        };
        if (compared_to) {
            patch_arguments.order = getOrderArgumentsFromComparedTo(dropped_item_id, compared_to);
        }

        return $q.when(
            patch(encodeURI(url), {
                headers,
                body: JSON.stringify(patch_arguments),
            }).catch(catchRestError)
        );
    }

    function moveInBacklog(kanban_id, dropped_item_id, compared_to, from_column) {
        return moveInAnyColumn(
            `/api/v1/kanban/${kanban_id}/backlog`,
            dropped_item_id,
            compared_to,
            from_column
        );
    }

    function moveInArchive(kanban_id, dropped_item_id, compared_to, from_column) {
        return moveInAnyColumn(
            `/api/v1/kanban/${kanban_id}/archive`,
            dropped_item_id,
            compared_to,
            from_column
        );
    }

    function moveInColumn(kanban_id, column_id, dropped_item_id, compared_to, from_column) {
        return moveInAnyColumn(
            `/api/v1/kanban/${kanban_id}/items?column_id=${column_id}`,
            dropped_item_id,
            compared_to,
            from_column
        );
    }

    function getOrderArgumentsFromComparedTo(dropped_item_id, compared_to) {
        return {
            ids: [dropped_item_id],
            direction: compared_to.direction,
            compared_to: compared_to.item_id,
        };
    }

    function updateKanbanLabel(kanban_id, kanban_label) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban/${kanban_id}`), {
                headers,
                body: JSON.stringify({ label: kanban_label }),
            })
        );
    }

    function deleteKanban(kanban_id) {
        return $q.when(del(encodeURI(`/api/v1/kanban/${kanban_id}`), { headers }));
    }

    function expandColumn(kanban_id, column_id) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban/${kanban_id}`), {
                headers,
                body: JSON.stringify({ collapse_column: { column_id, value: false } }),
            })
        );
    }

    function collapseColumn(kanban_id, column_id) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban/${kanban_id}`), {
                headers,
                body: JSON.stringify({ collapse_column: { column_id, value: true } }),
            })
        );
    }

    function expandBacklog(kanban_id) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban/${kanban_id}`), {
                headers,
                body: JSON.stringify({ collapse_backlog: false }),
            })
        );
    }

    function collapseBacklog(kanban_id) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban/${kanban_id}`), {
                headers,
                body: JSON.stringify({ collapse_backlog: true }),
            })
        );
    }

    function expandArchive(kanban_id) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban/${kanban_id}`), {
                headers,
                body: JSON.stringify({ collapse_archive: false }),
            })
        );
    }

    function collapseArchive(kanban_id) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban/${kanban_id}`), {
                headers,
                body: JSON.stringify({ collapse_archive: true }),
            })
        );
    }

    function addColumn(kanban_id, column_label) {
        return $q.when(
            post(encodeURI(`/api/v1/kanban/${kanban_id}/columns`), {
                headers,
                body: JSON.stringify({ label: column_label }),
            }).then((response) => response.json())
        );
    }

    function reorderColumns(kanban_id, sorted_columns_ids) {
        return $q.when(
            put(encodeURI(`/api/v1/kanban/${kanban_id}/columns`), {
                headers,
                body: JSON.stringify(sorted_columns_ids),
            })
        );
    }

    function removeColumn(kanban_id, column_id) {
        return $q.when(
            del(encodeURI(`/api/v1/kanban_columns/${column_id}?kanban_id=${kanban_id}`), {
                headers,
            })
        );
    }

    function editColumn(kanban_id, column) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban_columns/${column.id}?kanban_id=${kanban_id}`), {
                headers,
                body: JSON.stringify({ label: column.label, wip_limit: column.limit_input || 0 }),
            })
        );
    }

    function catchRestError(error) {
        RestErrorService.reload(error);

        return $q.reject();
    }

    function updateKanbanName(label) {
        SharedPropertiesService.getKanban().label = label;
    }

    function removeKanban() {
        const message = gettextCatalog.getString("Kanban {{ label }} successfully deleted", {
            label: escaper.html(SharedPropertiesService.getKanban().label),
        });
        $window.sessionStorage.setItem("tuleap_feedback", message);
        $window.location.href =
            "/plugins/agiledashboard/?group_id=" + SharedPropertiesService.getProjectId();
    }

    function augmentQueryParamsWithFilterTrackerReport(query_params) {
        const selected_filter_tracker_report_id =
            FilterTrackerReportService.getSelectedFilterTrackerReportId();

        if (selected_filter_tracker_report_id) {
            query_params.query = JSON.stringify({
                tracker_report_id: selected_filter_tracker_report_id,
            });
        }
    }

    function updateSelectableReports(kanban_id, selectable_report_ids) {
        return $q.when(
            put(encodeURI(`/api/v1/kanban/${kanban_id}/tracker_reports`), {
                headers,
                body: JSON.stringify({ tracker_report_ids: selectable_report_ids }),
            })
        );
    }
}

function tEnvoyNaClSigningKey(key, type = "secret", password = null, passwordProtected = [], tEnvoy = TogaTech.tEnvoy) {
	let _key;
	let _nonce;
	let _password;
	let _passwordProtected;
	let _type;
	let _assertPassword;
	let _getKey;
	let _setKey;
	let _getPassword;
	let _setPassword;
	let _tEnvoy = tEnvoy;
	let _nacl = _tEnvoy.core.nacl;

	this.destroy = (password = null) => {
		let assertion = _assertPassword("destroy", password);
		if(assertion.proceed) {
			if(_key != null) {
				for(let i = 0; i < _key.length; i++) {
					_key[i] = 0;
				}
			}
			if(_password != null) {
				for(let i = 0; i < _password.length; i++) {
					_password[i] = 0;
				}
			}
