			} else if(_type == "public") {
				if(_getPassword() == null) {
					return _tEnvoy.util.arrayDeepCopy(_getKey());
				} else {
					let decryptionKey = new tEnvoyNaClKey(_getPassword(), "secret", null, [], _tEnvoy);
					let decrypted = decryptionKey.decrypt(_getKey());
