				let alwaysProtected;
				if(_type == "private") {
					alwaysProtected = ["getPrivate", "setPrivate", "setPasswordProtected"];
				} else if(_type == "public") {
					alwaysProtected = ["getPublic", "setPublic", "setPasswordProtected"];
