							error: "tEnvoyNaClSigningKey Fatal Error: Key is password-protected for method " + methodName + ", and an incorrect password was specified."
						}
					} else {
						return {
							proceed: true
						};
					}
				} else {
					return {
						proceed: true
					};
				}
			}
		}
