function serialize (source, opts) {
  var out = ''
  var key
  var tmp
  var type
  var i

  opts = opts || {}
  if (!opts._visited) {
    opts._visited = []
  }
  if (!opts._refs) {
    opts.references = []
    opts._refs = new Ref(opts.references)
  }

