        if (!service) {
            return;
        }

        $('<strong/>', {
            'text': App.Utils.String.escapeHtml(service.name),
        }).appendTo($serviceDescription);

        if (service.description) {
            $('<br/>').appendTo($serviceDescription);

            $('<span/>', {
                'html': App.Utils.String.escapeHtml(service.description).replaceAll('\n', '<br/>')
